export function paintRoom(context,id,x,y,w,h,{rotation=0,preserve=false}={}){if(!roomAtlas.complete||!roomAtlas.naturalWidth)return;if(id==='floor'){context.drawImage(roomAtlas,741,627,275,275,x,y,w,h);return;}const s=sprites[id];let width=rotation%Math.PI!==0?h:w,height=rotation%Math.PI!==0?w:h;const [cx,cy,cw,ch]=s.crop;if(preserve){const scale=Math.min(width/cw,height/ch);width=cw*scale;height=ch*scale;}context.save();context.translate(x+w/2,y+h/2);context.rotate(rotation);context.translate(-width/2,-height/2);context.scale(width/cw,height/ch);context.translate(-cx,-cy);context.beginPath();s.clip.forEach(([px,py],i)=>i?context.lineTo(px,py):context.moveTo(px,py));context.closePath();context.clip();context.drawImage(roomAtlas,cx,cy,cw,ch,cx,cy,cw,ch);context.restore();}
